#!/bin/sh
# ALV-N021 A2 final evidence run, part 1 (cheap first; stops at the first failing stage). ApiTests are NOT here (asked separately).
OUT="$1"; R="C:/Users/firas/Documents/AI-Project-[Alveara-Dental]"; T="$2"
rm -rf "$OUT"; mkdir -p "$OUT/trx" "$OUT/gates"; S="$OUT/summary.txt"
{ echo "run commit: $(git -C "$R" rev-parse HEAD)"; echo "tree changed paths: $(git -C "$R" status --porcelain | wc -l)"; echo "start: $(date -Iseconds)"; } > "$S"
stop() { echo "== STOPPED after $1" >> "$S"; echo "end: $(date -Iseconds)" >> "$S"; exit 1; }
cd "$R/src/alveara-client" || exit 1
gate() { name="$1"; shift; g0=$(date +%s); "$@" > "$OUT/gates/$name.txt" 2>&1; code=$?; echo "== gate $name exit=$code elapsed=$(( $(date +%s) - g0 ))s: $(grep -E 'Tests  |Test Files|passed|failed|built in' "$OUT/gates/$name.txt" | tail -3 | tr '\n' ' ')" >> "$S"; [ $code -eq 0 ] || stop "$name"; }
# client gates and mocked Playwright ran green separately (vitest 2018/2018 in final1; mocked Playwright 165 passed after 0006779)
cd "$R" || exit 1
# repo checks 49/49 already at 265331c (unchanged since)
cd "$R/src" || exit 1
gate backend_build dotnet build Alveara.Api.Tests -nologo -v q
F="FullyQualifiedName~Alveara.Api.Tests.AppointmentLifecycleApiTests.|FullyQualifiedName~Alveara.Api.Tests.AppointmentLifecycleTests.|FullyQualifiedName~Alveara.Api.Tests.AppointmentMergeScopeMigrationTests.|FullyQualifiedName~Alveara.Api.Tests.AppointmentMoveDestinationMigrationTests.|FullyQualifiedName~Alveara.Api.Tests.AppointmentMoveHistoryTests.|FullyQualifiedName~Alveara.Api.Tests.BillingApiTests.|FullyQualifiedName~Alveara.Api.Tests.BillingLedgerApiTests.|FullyQualifiedName~Alveara.Api.Tests.BlockedTimeCalendarLabelMigrationTests.|FullyQualifiedName~Alveara.Api.Tests.BlockedTimeOverlapTests.|FullyQualifiedName~Alveara.Api.Tests.CalendarBlockedTimeApiTests.|FullyQualifiedName~Alveara.Api.Tests.CancelCategoryClientParityTests.|FullyQualifiedName~Alveara.Api.Tests.CancellationCategoryTests.|FullyQualifiedName~Alveara.Api.Tests.ChainClockAdvanceTests.|FullyQualifiedName~Alveara.Api.Tests.CheckInDstDayRuleTests.|FullyQualifiedName~Alveara.Api.Tests.CheckoutTests.|FullyQualifiedName~Alveara.Api.Tests.CollectPaymentsApiTests.|FullyQualifiedName~Alveara.Api.Tests.ConfigurationApiTests.|FullyQualifiedName~Alveara.Api.Tests.PatientFlowApiTests.|FullyQualifiedName~Alveara.Api.Tests.PatientFlowLifecycleTests.|FullyQualifiedName~Alveara.Api.Tests.PermissionPolicyHealthTests.|FullyQualifiedName~Alveara.Api.Tests.PermissionPolicyWriteTests.|FullyQualifiedName~Alveara.Api.Tests.PracticeDayBoundaryTests.|FullyQualifiedName~Alveara.Api.Tests.ProviderReassignmentTests.|FullyQualifiedName~Alveara.Api.Tests.RealMigrationInventoryTests.|FullyQualifiedName~Alveara.Api.Tests.StaffInactivationNotificationSchemaTests.|FullyQualifiedName~Alveara.Api.Tests.TimeCultureGuardTests.|FullyQualifiedName~Alveara.Api.Tests.UndoCheckInTests.|FullyQualifiedName~Alveara.Api.Tests.VisitActionsTests.|FullyQualifiedName~Alveara.Api.Tests.VisitBoardTests.|FullyQualifiedName~Alveara.Api.Tests.VisitCheckoutMigrationTests.|FullyQualifiedName~Alveara.Api.Tests.VisitFlowMeasurementTests.|FullyQualifiedName~Alveara.Api.Tests.VisitMovePolicyTests.|FullyQualifiedName~Alveara.Api.Tests.VisitOccupancyTests.|FullyQualifiedName~Alveara.Api.Tests.VisitPathTableTests.|FullyQualifiedName~Alveara.Api.Tests.VisitPermissionTests.|FullyQualifiedName~Alveara.Api.Tests.VisitStateMachineTests.|FullyQualifiedName~Alveara.Api.Tests.VisitWorkflowPermissionTests.|FullyQualifiedName~Alveara.Api.Tests.VisitWorkflowSchemaTests.|FullyQualifiedName~Alveara.Api.Tests.VisitWorkflowSettingsTests.|FullyQualifiedName~Alveara.Api.Tests.VisitWorkflowTests.|FullyQualifiedName~Alveara.Api.Tests.VisitsApiTests.|FullyQualifiedName~Alveara.Api.Tests.PatientMergeSchemaTests."
gate backend_focused dotnet test Alveara.Api.Tests -nologo --no-build --filter "$F" --logger "trx;LogFileName=backend-focused.trx" --results-directory "$OUT/trx"
grep -E 'Passed!|Failed!' "$OUT/gates/backend_focused.txt" | tail -1 >> "$S"
w0=$(date +%s); powershell -NoProfile -ExecutionPolicy Bypass -File "$T/run_walkthroughs_a2.ps1" -Out "$OUT/walk" > "$OUT/gates/walkthroughs.txt" 2>&1
cat "$OUT/walk/summary.txt" >> "$S"; echo "== walkthroughs elapsed=$(( $(date +%s) - w0 ))s" >> "$S"
grep -q "STOPPED" "$OUT/walk/summary.txt" && stop walkthroughs
c0=$(date +%s); powershell -NoProfile -ExecutionPolicy Bypass -File "$T/run_chain.ps1" -Out "$OUT/chain" > "$OUT/gates/chain.txt" 2>&1; code=$?
echo "== chain exit=$code elapsed=$(( $(date +%s) - c0 ))s: $(tail -3 "$OUT/gates/chain.txt" | tr '\n' ' ')" >> "$S"
echo "end: $(date -Iseconds)" >> "$S"; echo "tree changed paths after: $(git -C "$R" status --porcelain | wc -l)" >> "$S"; echo "== PART 1 DONE" >> "$S"
